#!/usr/bin/env bash
# Question 6: Install a service on ${Q6_NODE}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

runuser -u ubuntu -- ssh -o StrictHostKeyChecking=accept-new ${Q6_NODE} sudo bash -s <<'CKA_NODE_EOF'
set -euo pipefail
work=$(mktemp -d)
mkdir -p "$work/DEBIAN" "$work/usr/local/bin" "$work/lib/systemd/system"
cat > "$work/DEBIAN/control" <<'EOF'
Package: node-health-agent
Version: 1.0.0
Architecture: all
Maintainer: CKA Lab <lab@example.invalid>
Description: Writes a heartbeat for the node health dashboard
EOF
cat > "$work/usr/local/bin/node-health-agent" <<'EOF'
#!/bin/sh
mkdir -p /var/lib/node-health
while true; do date +%s > /var/lib/node-health/last; sleep 10; done
EOF
chmod 755 "$work/usr/local/bin/node-health-agent"
cat > "$work/lib/systemd/system/node-health-agent.service" <<'EOF'
[Unit]
Description=Node health agent
After=network-online.target

[Service]
ExecStart=/usr/local/bin/node-health-agent
Restart=always

[Install]
WantedBy=multi-user.target
EOF
dpkg -s node-health-agent >/dev/null 2>&1 && { systemctl disable --now node-health-agent >/dev/null 2>&1 || true; dpkg -r node-health-agent >/dev/null; }
rm -rf /opt/course/pkg /var/lib/node-health
mkdir -p /opt/course/pkg
dpkg-deb --root-owner-group --build "$work" /opt/course/pkg/node-health-agent_1.0.0_all.deb >/dev/null
chown -R ubuntu:ubuntu /opt/course
rm -rf "$work"
CKA_NODE_EOF
: "${Q6_NODE}"
